/** The marker every generated file carries; the drift check and `talos adopt` look for it. */
export const GENERATED_MARKER = 'Generated by Talos';

export type CommentStyle = '//' | '#' | '--' | ';';

/**
 * The first line of a generated file: what wrote it, at which version, and where the project's
 * own additions go instead.
 */
export function generatedHeader(style: CommentStyle, version: string, extension?: string): string {
  const where =
    extension === undefined
      ? 'Do not edit.'
      : `Do not edit: extend it in ${extension}, which may only tighten it.`;
  return `${style} ${GENERATED_MARKER} ${version}. ${where}\n`;
}

/** For JSON files, which carry no comments: the same words under a `//` key. */
export function generatedJsonNote(version: string, extension?: string): string {
  return generatedHeader('//', version, extension).slice(3).trim();
}
